def align(seq_a: str, seq_b: str, mode: str = "global",
          match: int = 2, mismatch: int = -3,
          gap_open: int = -5, gap_extend: int = -2) -> tuple[int, str, str]:
    # Handle empty sequences
    if not seq_a and not seq_b:
        return (0, "", "")
    if not seq_a:
        return (0, "", seq_b)
    if not seq_b:
        return (0, seq_a, "")

    # Initialize DP table
    len_a = len(seq_a)
    len_b = len(seq_b)
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    # Fill first row (seq_a is empty)
    for j in range(1, len_b + 1):
        dp[0][j] = dp[0][j-1] + gap_open + (j-1)*gap_extend

    # Fill first column (seq_b is empty)
    for i in range(1, len_a + 1):
        dp[i][0] = dp[i-1][0] + gap_open + (i-1)*gap_extend

    # Fill the rest of the table
    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            # Compute match/mismatch score
            if seq_a[i-1] == seq_b[j-1]:
                match_score = match
            else:
                match_score = mismatch
            # Compute the maximum of the three options
            option1 = dp[i-1][j-1] + match_score
            option2 = dp[i-1][j] + gap_extend
            option3 = dp[i][j-1] + gap_extend
            dp[i][j] = max(option1, option2, option3)

    # Determine the max score and reconstruct the alignment
    if mode == "local":
        # Find the maximum score in the DP table
        max_score = max(max(row) for row in dp)
        # Find the position of the maximum score
        for i in range(len_a + 1):
            for j in range(len_b + 1):
                if dp[i][j] == max_score:
                    # Reconstruct the alignment from (i,j) to (0,0)
                    aligned_a, aligned_b = reconstruct(i, j, seq_a, seq_b, dp, match, mismatch, gap_extend)
                    return (max_score, aligned_a, aligned_b)
    else:
        # Global mode: the best score is at (len_a, len_b)
        aligned_a, aligned_b = reconstruct(len_a, len_b, seq_a, seq_b, dp, match, mismatch, gap_extend)
        return (dp[len_a][len_b], aligned_a, aligned_b)

